import numpy as np
from scipy import stats

MAX_DRIVERS = 2

def design(feats):
    # Calculate mean differences for each feature
    means_y1 = np.array([np.mean(feats.x[feats.y==1, feats.column(fid)]) 
                         for fid in feats.ids])
    means_y0 = np.array([np.mean(feats.x[feats.y==0, feats.column(fid)]) 
                         for fid in feats.ids])
    diffs = means_y1 - means_y0

    # Sort by absolute difference
    idxs = np.argsort(np.abs(diffs))[::-1]

    # Remove correlated features (keep only one from each pair)
    keep = []
    used = set()
    for i in idxs:
        fid = feats.ids[i]
        if fid in used:
            continue
        keep.append(i)
        used.add(fid)

        # Check correlations with remaining features
        for j in idxs[i+1:]:
            fid2 = feats.ids[j]
            if fid2 in used:
                continue
            try:
                corr = np.corrcoef(feats.x[:, feats.column(fid)], 
                                  feats.x[:, feats.column(fid2)])[0,1]
                if abs(corr) >= 0.6:
                    used.add(fid2)
            except:
                continue

    # Select top features
    selected = [feats.ids[i] for i in keep[:MAX_DRIVERS]]

    # Check if any features have strong effect (p-value < 0.05)
    pvals = []
    for i, fid in enumerate(feats.ids):
        try:
            tstat, pval = stats.ttest_ind(feats.x[feats.y==1, feats.column(fid)], 
                                         feats.x[feats.y==0, feats.column(fid)])
            pvals.append(pval)
        except:
            pvals.append(1.0)

    # If no strong effect, return empty design
    if min(pvals) > 0.05:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use top features with strong effect
    top_features = []
    for i, fid in enumerate(feats.ids):
        if pvals[i] < 0.05 and fid in selected:
            top_features.append(fid)

    # Return design with drivers and their columns
    drivers = tuple(selected[:MAX_DRIVERS]) if selected else ()
    columns = tuple(top_features)
    products = ()
    loadings = {fid: 1.0 for fid in top_features}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

